#include <vector>
#include <limits>
#include <stdexcept>
#include <omp.h>

int smallestOdd(std::vector<int> const& x) {
    int result = std::numeric_limits<int>::max();
    int found_any = 0;
    const long long n = static_cast<long long>(x.size());

    #pragma omp parallel for default(none) shared(x, n) reduction(min:result) reduction(|:found_any)
    for (long long i = 0; i < n; ++i) {
        const int v = x[static_cast<std::size_t>(i)];
        if ((v % 2) != 0) {
            if (v < result) {
                result = v;
            }
            found_any = 1;
        }
    }

    if (found_any == 0) {
        throw std::invalid_argument("smallestOdd: input contains no odd numbers");
    }

    return result;
}
